def staged_payload_path(database, name):
    staging = database.parent / "staging"
    manifest = json.loads((staging / name).read_bytes())
    return staging / manifest["extents"][0]["object"]["name"]


def staged_bytes(database, name):
    """Independently reconstruct schema-17 storage for existing byte assertions."""
    staging = database.parent / "staging"
    encoded = (staging / name).read_bytes()
    with sqlite3.connect(database) as db:
        expected = db.execute("SELECT digest FROM dirty_roots WHERE root=?", (name,)).fetchone()[0]
        assert hashlib.sha256(encoded).hexdigest() == expected, "dirty root changed"
        manifest = json.loads(encoded)
        assert manifest["size"] <= 128 * 1024 * 1024, "use bounded reads for larger fixture files"
        result = bytearray(manifest["size"])
        covered = bytearray(manifest["visible_end"])

        def payload(obj):
            body = (staging / obj["name"]).read_bytes()
            assert len(body) == obj["size"]
            assert [hashlib.sha256(body[i:i+131072]).hexdigest() for i in range(0, len(body), 131072)] == obj["blocks"]
            return body

        for extent in manifest["extents"]:
            start, length, offset = extent["start"], extent["length"], extent["offset"]
            body = payload(extent["object"])
            result[start:start+length] = body[offset:offset+length]
            end = min(start+length, len(covered))
            if start < end:
                covered[start:end] = b"\1" * (end-start)
        if manifest["base"] is not None:
            objects = {offset: json.loads(obj) for version, offset, obj in db.execute("SELECT version,offset,object FROM dirty_bases") if json.loads(version) == manifest["base"]}
            for start in range(0, len(covered), 131072):
                end = min(start+131072, len(covered))
                if not all(covered[start:end]):
                    assert start in objects, "exact original content base is unavailable locally"
                    body = payload(objects[start])
                    for index in range(start, end):
                        if not covered[index]:
                            result[index] = body[index-start]
        return bytes(result)


