        def check_first_parent():
            nonlocal daemon,mounted,second_daemon,second_cli,server,thread
            database = runtime / "home/.local/state/cirrus-drive/state.db"
            dirty = b"retained dirty bytes across first parent publication"
            with open(mountpoint / "first-parent-dirty","wb",buffering=0) as file:
                file.write(dirty)
                os.fsync(file.fileno())
            fixture.require(cli("--pin-space",url,space,"/folder/nested.bin"),"retaining pin before first-parent test")
            fixture.require(cli("--set-storage-limits",512 * 1024 * 1024,0),"enabling first-parent State admission")
            with sqlite3.connect(database) as db:
                roots = db.execute("SELECT * FROM dirty_roots ORDER BY root").fetchall()
                pins = db.execute("SELECT * FROM pins ORDER BY instance,space,root").fetchall()

            def owner(label,process):
                ticks = Path(f"/proc/{process.pid}/stat").read_text().rsplit(")",1)[1].split()[19]
                print(f"OWNED first-parent {label}: root={root} runtime={runtime} container={container} pid={process.pid} start_ticks={ticks}",flush=True)

            def copies():
                with sqlite3.connect(database) as db:
                    return db.execute("SELECT path,entries,updated FROM snapshots WHERE instance=? AND space=? ORDER BY path",(url,project)).fetchall()

            def recovery(label):
                with sqlite3.connect(database) as db:
                    assert db.execute("SELECT * FROM dirty_roots ORDER BY root").fetchall() == roots
                    assert db.execute("SELECT * FROM pins ORDER BY instance,space,root").fetchall() == pins
                retained = [json.loads(line) for line in fixture.require(cli("--retained-staged",url),"listing first-parent dirty recovery").stdout.splitlines()]
                selected = max((row for row in retained if row["path"] == ["first-parent-dirty"]),key=lambda row:row["id"])
                output = runtime / ("first-parent-dirty-" + label)
                fixture.require(cli("--export-staged",url,selected["id"],selected["selector"],output),"exporting first-parent dirty root")
                assert output.read_bytes() == dirty
                retained_pin = [json.loads(line) for line in fixture.require(cli("--retained-files",url,space,"/folder/nested.bin"),"listing first-parent pin recovery").stdout.splitlines()]
                pin_output = runtime / ("first-parent-pin-" + label)
                fixture.require(cli("--export-retained",url,space,"/folder/nested.bin","/folder/nested.bin",retained_pin[0]["selector"],pin_output),"exporting retained pin after snapshot invalidation")
                assert pin_output.read_bytes() == contents["folder/nested.bin"]

            def offline():
                nonlocal server,thread
                server.shutdown()
                server.server_close()
                thread.join(timeout=5)
                server = thread = None

