                assert lab.upstream(container,"MKCOL",base + "/review-dir")[0] == 201
                assert lab.upstream(container,"PUT",base + "/review-dir/new",b"new B child")[0] == 201
                requests_before = count("PROPFIND","/")
                try: os.listdir(mountpoint)
                except OSError as error: assert error.errno == errno.EIO,error
                else: raise AssertionError("replacement B published while descendant revocation was lease-blocked")
                assert count("PROPFIND","/") > requests_before
                with sqlite3.connect(database) as db:
                    assert db.execute("SELECT path,entries FROM snapshots WHERE instance=? AND space=? AND path IN ('[]','[\"review-dir\"]') ORDER BY path",(url,space)).fetchall() == saved
                peer_window.unlink()
                peer_worker.join(timeout=20)
                assert not peer_worker.is_alive()
                offline()
