                remount()
                assert os.listdir(mountpoint / "review-dir") == ["old"]
                online()
                assert "review-dir" in os.listdir(mountpoint)
                assert os.listdir(mountpoint / "review-dir") == ["new"]
                assert read_file(mountpoint / "review-dir/new") == b"new B child"
                export(["review-dirty"],protected_bytes,"B-online")
                offline()
                restart("offline-B")
                remount()
                assert os.listdir(mountpoint / "review-dir") == ["new"]
                assert "old" not in os.listdir(mountpoint / "review-dir")
                export(["review-dirty"],protected_bytes,"B-offline")
                online()
                # 2: kill after the parent's private E0->E1 update, before the
                # child's confirmation. The entire uncapped transaction rolls
                # back; both manual and automatic receipts remain restartable.
                for mode in ("manual","automatic"):
                    parent = "/review-rebase-" + mode
                    assert lab.upstream(container,"MKCOL",base + parent)[0] == 201
                    assert lab.upstream(container,"PUT",base + parent + "/child",b"delete child")[0] == 201
                    assert parent[1:] in os.listdir(mountpoint)
                    assert os.listdir(mountpoint / parent[1:]) == ["child"]
                    os.unlink(mountpoint / parent[1:] / "child")
                    os.rmdir(mountpoint / parent[1:])
                    with sqlite3.connect(database) as db:
                        row = db.execute("SELECT id,base_etag FROM operation_journal WHERE path=? AND op_type='rmdir'",(json.dumps([parent[1:]],separators=(',',':')),)).fetchone()
                    marker = root / "review-rebase"
                    marker.with_suffix(".waiting").unlink(missing_ok=True)
                    marker.touch(mode=0o600)
