                        enumeration_fd = os.open(directory, os.O_RDONLY | os.O_DIRECTORY)
                        first = fault_page(enumeration_fd)
                        cookie = first[-1][1]
                        second = fault_page(enumeration_fd)
                        before = first + second + fault_drain(enumeration_fd)
                        before_map = {name: inode for name, _, inode in before if name not in (".", "..")}
                        assert set(before_map) == original_names
                        with sqlite3.connect(database) as db:
                            dirty_root = db.execute("SELECT id,staged_file,base_file_id,base_etag FROM operation_journal WHERE path=? ORDER BY id DESC LIMIT 1", ('["reconcile","dirty"]',)).fetchone()
