        if os.environ.get("CIRRUS_TEST_FILE_RENAME_PREPARATION"):
            source = mountpoint / "file-prep-source"
            target = mountpoint / "file-prep-target"
            marker = root / "file-rename-prep-window"
            failures = []
            steps = []
            unrelated_done = threading.Event()
            source_write_started = threading.Event()
            source_written = threading.Event()
            with open(source, "w+b", buffering=0) as source_file, open(mountpoint / "file-prep-unrelated", "w+b", buffering=0) as writer:
                source_file.write(b"before")
                os.fsync(source_file.fileno())
                def rename_file():
                    try:
                        os.rename(source, target)
                    except OSError as error:
                        failures.append(error)
                def write_files():
                    try:
                        steps.append("unrelated write")
                        os.pwrite(writer.fileno(), b"unrelated durable write", 0)
                        os.fsync(writer.fileno())
                        unrelated_done.set()
                        steps.append("source write")
                        source_write_started.set()
                        os.pwrite(source_file.fileno(), b"later!", 0)
                        source_written.set()
                        os.fsync(source_file.fileno())
                        steps.append("done")
                    except OSError as error:
                        failures.append(error)
                marker.touch(mode=0o600)
                rename = threading.Thread(target=rename_file)
                worker = threading.Thread(target=write_files)
                rename.start()
                try:
                    deadline = time.monotonic() + 10
                    while not marker.with_suffix(".waiting").exists() and time.monotonic() < deadline:
                        time.sleep(0.02)
                    assert marker.with_suffix(".waiting").exists(), "file rename did not reach metadata window"
                    worker.start()
                    assert unrelated_done.wait(timeout=5), f"unrelated write/fsync stalled: steps={steps}, errors={failures}"
                    assert source_write_started.wait(timeout=5), f"same-file write did not start: steps={steps}, errors={failures}"
                    # Linux queues the direct write behind rename's source-inode
                    # lock; it need not reach the daemon during preparation.
                    worker.join(timeout=0.2)
                    assert rename.is_alive() and worker.is_alive() and not source_written.is_set() and not failures, f"same-file write did not wait for rename: steps={steps}, errors={failures}"
                finally:
                    marker.unlink(missing_ok=True)
                    rename.join(timeout=30)
                    if worker.ident is not None:
                        worker.join(timeout=30)
                assert not rename.is_alive() and not worker.is_alive() and not failures, failures
                assert source_written.is_set(), "same-file write did not finish after rename was released"
                assert steps == ["unrelated write", "source write", "done"], steps
                assert os.pread(source_file.fileno(), 6, 0) == b"later!"
                assert read_file(target) == b"later!"
                assert not source.exists()
                assert read_file(mountpoint / "file-prep-unrelated") == b"unrelated durable write"
                fixture.require(cli("--sync", url), "syncing file rename after concurrent writes")
                assert lab.upstream(container, "GET", base + "/file-prep-target")[2] == b"later!"
                assert lab.upstream(container, "GET", base + "/file-prep-unrelated")[2] == b"unrelated durable write"
                assert os.pread(source_file.fileno(), 6, 0) == b"later!"
                assert read_file(target) == b"later!"
            print("PASS: unrelated write/fsync completes during file rename preparation; queued same-file edit survives rename and sync", flush=True)
            return
