            assert read_file(mountpoint / "folder" / "rename-hydrate-target") == b"remote source bytes"
            fixture.require(cli("--sync", url), "syncing rename after hydration")
            assert lab.upstream(container, "GET", base + "/folder/rename-hydrate-target")[2] == b"remote source bytes"
            assert lab.upstream(container, "GET", base + "/unrelated-hydrate-write")[2] == b"saved during hydration"
            print("PASS: remote file rename metadata preparation permits an unrelated durable write and retains the open target", flush=True)
            return
