            assert pair_target.stat().st_size == len(contents["folder/write-open-pair"])
            directory_continue.clear()
            blocked_open_pair.clear()
            with blocked_open_lock:
                blocked_open_count[0] = 0
            fds = []
            def open_pair():
                try:
                    fds.append(os.open(pair_target, os.O_RDWR))
                except OSError as error:
                    failures.append(error)
            openers = [threading.Thread(target=open_pair) for _ in range(2)]
            for thread_open in openers:
                thread_open.start()
            try:
                assert blocked_open_pair.wait(timeout=10), "concurrent writable opens did not reach metadata together"
            finally:
                directory_continue.set()
                for thread_open in openers:
                    thread_open.join(timeout=30)
            try:
                assert all(not thread_open.is_alive() for thread_open in openers) and not failures and len(fds) == 2, failures
                assert os.pwrite(fds[0], b"A", 0) == 1
                assert os.pwrite(fds[1], b"B", 1) == 1
                assert os.pread(fds[0], 4, 0) == b"ABig"
                assert os.pread(fds[1], 4, 0) == b"ABig"
            finally:
                for fd in fds:
                    os.close(fd)
            original_pair = read_file(pair_target)
            fds = []
            try:
                for _ in range(128):
                    fds.append(os.open(pair_target, os.O_RDONLY))
                try:
                    fd = os.open(pair_target, os.O_WRONLY | os.O_TRUNC)
                except OSError as error:
                    assert error.errno == errno.EMFILE, error
                else:
                    os.close(fd)
                    raise AssertionError("writable open exceeded the mount handle limit")
            finally:
                for fd in fds:
                    os.close(fd)
            assert read_file(pair_target) == original_pair, "failed O_TRUNC open changed staged data"
            held_target = mountpoint / "folder" / "write-open-held"
            with open(held_target, "rb", buffering=0) as held:
                assert held.read() == contents["folder/write-open-held"]
                assert lab.upstream(container, "PUT", base + "/folder/write-open-held", b"new held version")[0] == 204
                try:
                    fd = os.open(held_target, os.O_RDWR)
                except OSError as error:
                    assert error.errno == errno.EBUSY, error
                else:
                    os.close(fd)
                    raise AssertionError("writable open rebound an existing handle to another version")
            with open(held_target, "r+b", buffering=0) as reopened:
                assert reopened.read() == b"new held version"
            invalidated_target = mountpoint / "folder" / "write-open-invalidated"
            with open(invalidated_target, "rb", buffering=0) as held:
                assert held.read() == contents["folder/write-open-invalidated"]
